    enonce: "بيّن أنّ العدد <span dir=\"ltr\" class=\"expr\">3<sup>127</sup> + 3<sup>129</sup></span> يقبل القسمة على 18",
    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>129</sup> = 3<sup>127</sup> × 3<sup>2</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">3<sup>127</sup> + 3<sup>129</sup> = 3<sup>127</sup>(1 + 3<sup>2</sup></span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 + 3<sup>2</sup> = 10</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">3<sup>127</sup> + 3<sup>129</sup> = 10 × 3<sup>127</sup></span>"},{"quoi":"نُظهر القاسم 18","math":"<span dir=\"ltr\" class=\"expr\">10 × 3<sup>127</sup> = 18 × (5 × 3<sup>125</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">18 × 5 × 3<sup>125</sup></span> و منه يقبل القسمة على 18"}],
