    enonce: "بيّن أنّ العدد <span dir=\"ltr\" class=\"expr\">125<sup>38</sup> - 25<sup>58</sup></span> يقبل القسمة على 75",
    correction: [{"quoi":"القاعدة","math":"لا يمكن جمع قوّتين إلاّ إذا كان لهما نفس الأساس"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">125<sup>38</sup> = 5<sup>114</sup></span>"},{"quoi":"نوحّد الأساس في الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">25<sup>58</sup> = 5<sup>116</sup></span>"},{"quoi":"نعيد كتابة العدد","math":"<span dir=\"ltr\" class=\"expr\">125<sup>38</sup> - 25<sup>58</sup> = 5<sup>114</sup> - 5<sup>116</sup></span>"},{"quoi":"نُخرج أصغر قوّة","math":"<span dir=\"ltr\" class=\"expr\">5<sup>114</sup> - 5<sup>116</sup> = 5<sup>114</sup>(1 - 5<sup>2</sup></span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 - 5<sup>2</sup> = -24</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">125<sup>38</sup> - 25<sup>58</sup> = -24 × 5<sup>114</sup></span>"},{"quoi":"نُظهر القاسم 75","math":"<span dir=\"ltr\" class=\"expr\">-24 × 5<sup>114</sup> = 75 × ((-8) × 5<sup>112</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">75 × (-8) × 5<sup>112</sup></span> و منه يقبل القسمة على 75"}],
