    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">25<sup>766</sup> = 5<sup>1532</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">5<sup>1532</sup> + n × 5<sup>1529</sup> = 5<sup>1529</sup>(5<sup>3</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">175 = 25 × 7</span>"},{"quoi":"العامل 25 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">5<sup>1529</sup> = 5<sup>2</sup> × 5<sup>1527</sup></span>"},{"quoi":"يبقى الشرط على 7","math":"بما أنّ 7 و 5 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">5<sup>3</sup> + n</span> القسمة على 7"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">5<sup>3</sup> = 125</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 50 بحيث يقبل <span dir=\"ltr\" class=\"expr\">125 + n</span> القسمة على 7"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 8 ؛ 15 ؛ 22 ؛ 29 ؛ 36 ؛ 43</span>"}],
