    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">4<sup>857</sup> = 2<sup>1714</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>1715</sup> + n × 2<sup>1714</sup> = 2<sup>1714</sup>(2 + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">22 = 2 × 11</span>"},{"quoi":"العامل 2 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">2<sup>1714</sup> = 2 × 2<sup>1713</sup></span>"},{"quoi":"يبقى الشرط على 11","math":"بما أنّ 11 و 2 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">2 + n</span> القسمة على 11"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">2 = 2</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 60 بحيث يقبل <span dir=\"ltr\" class=\"expr\">2 + n</span> القسمة على 11"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 9 ؛ 20 ؛ 31 ؛ 42 ؛ 53</span>"}],
