    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">4<sup>575</sup> = 2<sup>1150</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>1150</sup> + n × 2<sup>1148</sup> = 2<sup>1148</sup>(2<sup>2</sup> + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">14 = 2 × 7</span>"},{"quoi":"العامل 2 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">2<sup>1148</sup> = 2 × 2<sup>1147</sup></span>"},{"quoi":"يبقى الشرط على 7","math":"بما أنّ 7 و 2 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">2<sup>2</sup> + n</span> القسمة على 7"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">2<sup>2</sup> = 4</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 60 بحيث يقبل <span dir=\"ltr\" class=\"expr\">4 + n</span> القسمة على 7"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 3 ؛ 10 ؛ 17 ؛ 24 ؛ 31 ؛ 38 ؛ 45 ؛ 52 ؛ 59</span>"}],
